<script setup>
import {ref,onMounted} from 'vue'
import {request} from './client'
const props=defineProps({control:Boolean})
const rows=ref([]),media=ref([]),error=ref(''),notice=ref(''),busy=ref(false),reason=ref(''),page=ref(0)
async function run(fn){busy.value=true;error.value='';try{await fn()}catch(e){error.value=e.message}finally{busy.value=false}}
async function load(){await run(async()=>{rows.value=await request(props.control?'commerce_events':'lecture_refunds','listing',{page:page.value},'GET');if(!props.control)media.value=await request('media_reconciliation','listing',{},'GET')})}
async function refund(row){if(!confirm('Request a full refund? Access is revoked only after provider confirmation.'))return;await run(async()=>{const r=await request('lecture_refunds','request',{order:row.name,reason:reason.value});notice.value=`Refund ${r.status}. ${r.message||''}`});await load()}
async function cleanup(row){if(!confirm('Remove all versions of this expired unused upload? Referenced content is protected by the backend.'))return;await run(async()=>{const r=await request('media_reconciliation','cleanup',{name:row.name,reason:reason.value});notice.value=r.status});await load()}
onMounted(load)
</script>
<template><article class="panel"><h2>{{control?'Tenant commerce reports':'Finance & media reconciliation'}}</h2><p v-if="control">Signed tenant-reported metadata only. No student identity, course contents or cross-site database queries. Repeated lifecycle events are not additional revenue.</p><p v-if="busy" role="status">Loading…</p><p v-if="error" role="alert">{{error}}</p><p v-if="notice" role="status">{{notice}}</p><button class="button subtle" @click="load">Refresh</button><label v-if="!control">Audit reason<input v-model="reason" minlength="10" maxlength="500"></label><p v-if="!rows.length&&!busy">No records available.</p><div class="scroll"><table><thead><tr><th>Reference</th><th>Purpose / tenant</th><th>Status</th><th>Amount</th><th>Action</th></tr></thead><tbody><tr v-for="r in rows" :key="r.name||r.event_key"><td>{{r.receipt_number||r.reference_hash||r.name}}</td><td>{{r.purpose||'Lesson'}} {{r.tenant_id}}</td><td>{{r.status}} {{r.delivery_status}}</td><td>{{r.currency}} {{(r.amount_minor/100).toFixed(2)}}</td><td><button v-if="!control&&r.status==='succeeded'" class="button subtle" :disabled="busy||reason.length<10" @click="refund(r)">Request / reconcile refund</button></td></tr></tbody></table></div><template v-if="control"><button class="button subtle" :disabled="page===0||busy" @click="page--;load()">Previous</button><button class="button subtle" :disabled="rows.length<50||busy" @click="page++;load()">Next</button></template><template v-else><h3>Unconfirmed media reservations</h3><p>Cleanup requires 24 hours, confirmed remote removal and no sold or published references.</p><article v-for="m in media" :key="m.name"><p>{{m.name}} · {{m.media_state}} · {{m.bytes}} bytes · {{m.creation}}</p><button class="button subtle" :disabled="busy||reason.length<10" @click="cleanup(m)">Clean up unused reservation</button></article></template></article></template>
